import os
import json
import asyncpg
import uvicorn
import httpx
from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware

# Itt használd az összes kulcsodat "keménykódolva" vagy .env-ből, ahogy kedved tartja!
CEREBRAS_API_KEY="csk-jw6drkvjmyfwfwxpfmc8rx32v6j8kpm93ymt8vdt8nw882vd"
EXA_API_KEY="e9555015-688b-448d-ac17-850b1afd4cef"
GEMINI_API_KEY="AIzaSyDqglh_L7dBWaSgdPAU2Y-KTzxFrLYubU8"
DATABASE_URL="postgresql://neondb_owner:npg_DLJWrg4lb8uC@ep-white-sea-adb5mp8j.c-2.us-east-1.aws.neon.tech/neondb?sslmode=require"

CAR_INFO = {
    "VIN": "C177882", "Prod_Date": "2009-02-12", "Type": "520d",
    "Series": "E60", "Body_Type": "Sedan", "Steering": "Left",
    "Engine": "N47", "Power": "130kw / 177hp", "Drive": "rwd",
    "Colour": "black-sapphire metallic", "Upholstery": "Leather Dakota/natural brown"
}

app = FastAPI()
app.add_middleware(
    CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"]
)

async def get_db_pool():
    return await asyncpg.create_pool(DATABASE_URL, min_size=1, max_size=5)

db_pool = None

@app.on_event("startup")
async def startup():
    global db_pool
    db_pool = await get_db_pool()
    async with db_pool.acquire() as conn:
        await conn.execute("""
            CREATE TABLE IF NOT EXISTS queries (
                id SERIAL PRIMARY KEY,
                question TEXT, cerebras_answer TEXT, exa_answer TEXT,
                gemini_answer TEXT, final_answer TEXT, created_at TIMESTAMPTZ DEFAULT NOW()
            )
        """)

@app.on_event("shutdown")
async def shutdown():
    await db_pool.close()

def build_prompt(question):
    infotext = "\n".join([f"{k}: {v}" for k,v in CAR_INFO.items()])
    return f"""Autó adataim:
{infotext}

Kérdés: {question}
Adj részletes, tényalapú választ magyarul szakértőként!
Ha nem tudod biztosan, hogy igaz, írd is bele. Köszi."""

async def call_cerebras(prompt: str) -> str:
    url = "https://api.cerebras.cloud/v1/chat/completions"
    headers = {"Authorization": f"Bearer {CEREBRAS_API_KEY}", "Content-Type": "application/json"}
    data = {
        "model": "llama-4-scout-7b-8192",
        "messages": [{"role": "user", "content": prompt}], "stream": False
    }
    async with httpx.AsyncClient(timeout=20) as client:
        resp = await client.post(url, headers=headers, json=data)
        resp.raise_for_status()
        return resp.json()["choices"][0]["message"]["content"]

async def call_exa(prompt: str) -> str:
    url = "https://api.exa.ai/v1/generate"
    headers = {"Authorization": f"Bearer {EXA_API_KEY}", "Content-Type": "application/json"}
    data = {"prompt": prompt, "model": "default"}
    async with httpx.AsyncClient(timeout=20) as client:
        resp = await client.post(url, headers=headers, json=data)
        resp.raise_for_status()
        return resp.json().get("output", "")

async def call_gemini(prompt: str) -> str:
    url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key={GEMINI_API_KEY}"
    headers = {"Content-Type": "application/json"}
    data = {"contents": [{"role": "user", "parts": [{"text": prompt}]}]}
    async with httpx.AsyncClient(timeout=20) as client:
        resp = await client.post(url, headers=headers, json=data)
        resp.raise_for_status()
        try:
            return resp.json()["candidates"][0]["content"]["parts"][0]["text"]
        except Exception:
            return json.dumps(resp.json())

@app.post("/ask")
async def ask_question(request: Request):
    body = await request.json()
    question = body.get("question")
    if not question:
        raise HTTPException(400, detail="Kérdés megadása kötelező!")
    prompt = build_prompt(question)
    cerebras_task = call_cerebras(prompt)
    exa_task = call_exa(prompt)
    gemini_task = call_gemini(prompt)
    cerebras_answer, exa_answer, gemini_answer = await cerebras_task, await exa_task, await gemini_task
    final_answer = f"{cerebras_answer}\n---\n[Exa]: {exa_answer}\n---\n[Gemini]: {gemini_answer}"
    async with db_pool.acquire() as conn:
        await conn.execute("""
            INSERT INTO queries (question, cerebras_answer, exa_answer, gemini_answer, final_answer)
            VALUES ($1, $2, $3, $4, $5)
        """, question, cerebras_answer, exa_answer, gemini_answer, final_answer)
    return {
        "question": question,
        "response": final_answer
    }

@app.get("/history")
async def get_history(limit: int = 20):
    async with db_pool.acquire() as conn:
        rows = await conn.fetch("SELECT id, question, final_answer, created_at FROM queries ORDER BY created_at DESC LIMIT $1", limit)
        return [{"id": r["id"], "question": r["question"], "answer": r["final_answer"], "created_at": str(r["created_at"])} for r in rows]

@app.get("/")
async def root():
    return {"status": "ok", "message": "BMW AI Hybrid Assistant fut (State of Art)!"}

