'use client';
import React, { useState } from 'react';
import { Box, Typography, Button, TextField, CircularProgress, Container, Paper, List, ListItem, ListItemText } from '@mui/material';
import useSWR from 'swr';

const fetcher = (url: string) => fetch(url).then(res => res.json());

export default function HomePage() {
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { data: history, mutate } = useSWR('/api/history', fetcher);

  const handleAsk = async () => {
    if (!question.trim()) return;
    setError('');
    setAnswer('');
    setLoading(true);
    try {
      const res = await fetch('/api/ask', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ question })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Hiba!');
      setAnswer(data.response);
      await mutate(); // frissíti a history listát
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container maxWidth="md" sx={{ mt: 6 }}>
      <Paper elevation={7} sx={{ p: 4, bgcolor: 'background.default' }}>
        <Typography variant="h3" gutterBottom color="primary">
          BMW AI Hybrid Assistant (E60 520d)
        </Typography>
        <Box sx={{ my: 3 }}>
          <TextField
            id="question"
            fullWidth
            value={question}
            label="Tegyen fel egy kérdést az autóról…"
            multiline
            minRows={2}
            onChange={e => setQuestion(e.target.value)}
            disabled={loading}
          />
          <Button
            sx={{ mt: 2 }}
            variant="contained"
            size="large"
            onClick={handleAsk}
            disabled={loading || !question}
          >{loading ? <CircularProgress size={24} /> : 'Küldés'}
          </Button>
        </Box>
        {error && <Typography color="error">{error}</Typography>}
        {answer && (
          <Paper elevation={1} sx={{ p: 2, mt: 3, background: '#1c2331' }}>
            <Typography variant="h6" color="secondary">Válasz:</Typography>
            <Typography sx={{ whiteSpace: 'pre-line' }}>{answer}</Typography>
          </Paper>
        )}
        <Box sx={{ mt: 6 }}>
          <Typography variant="h5" color="primary.light" gutterBottom>
            Előző kérdések & válaszok:
          </Typography>
          <History />
        </Box>
      </Paper>
    </Container>
  );
}

// Előzmények komponens
function History() {
  const { data: history } = useSWR('/api/history', fetcher, { refreshInterval: 5000 });
  if (!history) return <CircularProgress />;
  return (
    <List>
      {history.map((h: any) => (
        <ListItem key={h.id} alignItems="flex-start" sx={{ background: '#171a22', mb: 2, borderRadius: 1 }}>
          <ListItemText
            primary={<b>{h.question}</b>}
            secondary={<Typography sx={{ whiteSpace: 'pre-line' }}>{h.answer}</Typography>}
          />
        </ListItem>
      ))}
    </List>
  );
}


