const questionField = document.getElementById('question');
const answerBox = document.getElementById('answerBox');
const errorBox = document.getElementById('errorBox');
const historyList = document.getElementById('history');

async function loadHistory() {
    historyList.innerHTML = '<li class="mui-list-item">Betöltés...</li>';
    const res = await fetch('/api/history');
    const data = await res.json();
    historyList.innerHTML = '';
    if (!data.length) {
        historyList.innerHTML = '<li class="mui-list-item">Nincs előzmény.</li>';
        return;
    }
    for (const h of data) {
        const li = document.createElement('li');
        li.className = 'mui-list-item';
        li.innerHTML = `<div class="question"><b>Kérdés:</b> ${h.question}</div>
                        <div class="answer"><b>Válasz:</b><br><pre>${h.answer}</pre></div>`;
        historyList.appendChild(li);
    }
}

askForm.onsubmit = async e => {
    e.preventDefault();
    const question = questionField.value.trim();
    if (!question) return;
    answerBox.style.display = 'none';
    errorBox.style.display = 'none';
    answerBox.innerHTML = 'Dolgozom... <span class="material-icons">auto_mode</span>';
    answerBox.style.display = 'block';
    try {
        const res = await fetch('/api/ask', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({question})
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.detail || 'API hiba');
        answerBox.innerHTML = `<b>Válasz:</b><br><pre>${data.response}</pre>`;
        await loadHistory();
        questionField.value = '';
    } catch (err) {
        answerBox.style.display = 'none';
        errorBox.innerText = err.message;
        errorBox.style.display = 'block';
    }
};

window.onload = loadHistory;
</script>
