async def call_cerebras(prompt: str) -> str:
    url = "https://api.cerebras.cloud/v1/chat/completions"
    headers = {"Authorization": f"Bearer {CEREBRAS_API_KEY}", "Content-Type":"application/json"}
    data = {"model":"llama-4-scout-7b-8192","messages":[{"role":"user","content":prompt}],"stream":False}
    async with httpx.AsyncClient(timeout=20) as client:
        r = await client.post(url, headers=headers, json=data)
        r.raise_for_status()
        return r.json()["choices"][0]["message"]["content"]

async def call_exa(prompt: str) -> str:
    url = "https://api.exa.ai/v1/generate"
    headers = {"Authorization": f"Bearer {EXA_API_KEY}", "Content-Type": "application/json"}
    data = {"prompt": prompt, "model": "default"}
    async with httpx.AsyncClient(timeout=20) as client:
        r = await client.post(url, headers=headers, json=data)
        r.raise_for_status()
        return r.json()["output"]

async def call_gemini(prompt: str) -> str:
    url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key={GEMINI_API_KEY}"
    headers = {"Content-Type": "application/json"}
    data = {"contents":[{"role":"user","parts":[{"text":prompt}]}]}
    async with httpx.AsyncClient(timeout=20) as client:
        r = await client.post(url, headers=headers, json=data)
        r.raise_for_status()
        try:
            return r.json()["candidates"][0]["content"]["parts"][0]["text"]
        except Exception: return str(r.json())

@app.post("/api/ask")
async def ask(request: Request):
    j = await request.json()
    q = j.get("question", "").strip()
    if not q: raise HTTPException(400, "Kérdés kötelező!")
    prompt = build_prompt(q)
    res1, res2, res3 = await asyncio.gather(
        call_cerebras(prompt), call_exa(prompt), call_gemini(prompt)
    )
    final = f"Cerebras: {res1}\n\nExa: {res2}\n\nGemini: {res3}"
    async with _db.acquire() as c:
        await c.execute("INSERT INTO queries (question, cerebras, exa, gemini, final) VALUES ($1,$2,$3,$4,$5)",
                        q, res1, res2, res3, final)
    return {"response":final}

